import { ErrorCobria } from '../../domain/error-cobria.mjs';

const tokens = text => new Set(String(text).toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu, '').split(/\W+/u).filter(Boolean));
const similarity = (query, text) => {
  const expected = tokens(query); const actual = tokens(text);
  return [...expected].filter(token => actual.has(token)).length / Math.max(expected.size, 1);
};

export class RecuperarEvidencia {
  constructor({ repositorio, autorizar, umbral = 0.5 }) {
    this.repositorio = repositorio;
    this.autorizar = autorizar;
    this.umbral = umbral;
  }

  async ejecutar({ consulta, ambito }, contexto) {
    this.autorizar(contexto, 'observaciones:leer', ambito);
    if (!consulta?.trim()) throw new ErrorCobria('AI_QUERY_REQUIRED', 'La consulta de evidencia es obligatoria');
    const autorizados = await this.repositorio.listar(ambito);
    const citas = autorizados
      .map(item => ({ id: item.id, revision: item.revision, ambito: item.ambito, puntuacion: similarity(consulta, `${item.especie} ${item.cantidad}`) }))
      .filter(item => item.puntuacion >= this.umbral)
      .sort((a, b) => b.puntuacion - a.puntuacion || a.id.localeCompare(b.id));
    if (!citas.length) return Object.freeze({ estado: 'abstencion', causa: 'EVIDENCIA_INSUFICIENTE', citas: [], autoridadEscritura: false });
    return Object.freeze({ estado: 'evidencia-encontrada', citas, autoridadEscritura: false });
  }
}

import { ErrorCobria } from '../../domain/error-cobria.mjs';

export function construirConjuntoAnalitico({ documentos, ambito, corteTemporal, transformacion, calcularHuella, semilla = 20260921 }) {
  if (!ambito || !corteTemporal || !transformacion?.nombre || !transformacion?.version || typeof calcularHuella !== 'function') throw new ErrorCobria('ANALYTICS_CONFIG_INVALID', 'La configuración analítica no es válida');
  const corte = new Date(corteTemporal).getTime();
  if (!Number.isFinite(corte)) throw new ErrorCobria('ANALYTICS_CUTOFF_INVALID', 'El corte temporal no es válido');

  const elegibles = documentos
    .filter(item => item.ambito === ambito && item.consentimientoAnalitico === true)
    .map(item => ({ ...item, tiempoValido: new Date(item.observadaEn).getTime(), tiempoConocido: new Date(item.conocidaEn).getTime() }))
    .filter(item => Number.isFinite(item.tiempoValido) && Number.isFinite(item.tiempoConocido) && item.tiempoConocido <= corte)
    .sort((a, b) => a.id.localeCompare(b.id) || a.tiempoValido - b.tiempoValido);

  const entrenamiento = elegibles.filter(item => item.tiempoValido <= corte);
  const evaluacion = elegibles.filter(item => item.tiempoValido > corte);
  const idsEntrenamiento = new Set(entrenamiento.map(item => item.entidadId));
  if (evaluacion.some(item => idsEntrenamiento.has(item.entidadId))) throw new ErrorCobria('ANALYTICS_ENTITY_LEAKAGE', 'La partición presenta fuga entre entidades');

  const fuentes = elegibles.map(item => ({ id: item.id, revision: item.revision, ambito: item.ambito, huella: calcularHuella(item) }));
  const base = {
    contrato: 'cobria-conjunto-analitico-v1', ambito, corteTemporal: new Date(corte).toISOString(),
    transformacion, semilla, fuentes, exclusiones: { sinConsentimientoOAmbito: documentos.length - elegibles.length },
    particion: { estrategia: 'entidad-tiempo', entrenamiento: entrenamiento.map(item => item.id), evaluacion: evaluacion.map(item => item.id) },
  };
  return Object.freeze({ ...base, huella: calcularHuella(base), autoridadEscritura: false });
}

import { ErrorCobria } from '../../domain/error-cobria.mjs';

const AMBITO_VALIDO = /^[a-z0-9][a-z0-9-]{2,63}$/;

export function crearAutorizador({ auditar, ahora = () => new Date().toISOString() }) {
  return (contexto, capacidad, ambito) => {
    const actorId = contexto?.actorId?.trim();
    const finalidad = contexto?.finalidad?.trim();
    const base = { actorId: actorId || 'anonimo', capacidad, ambito, finalidad: finalidad || 'no-declarada' };

    if (!AMBITO_VALIDO.test(ambito ?? '')) {
      auditar({ ...base, resultado: 'denegado', codigo: 'SCOPE_INVALID', ocurridoEn: ahora() });
      throw new ErrorCobria('SCOPE_INVALID', 'Ámbito inválido');
    }

    const autorizado = actorId && finalidad
      && contexto?.permisos?.includes(capacidad)
      && contexto?.ambitos?.includes(ambito);

    if (!autorizado) {
      auditar({ ...base, resultado: 'denegado', codigo: 'ACCESS_DENIED', ocurridoEn: ahora() });
      throw new ErrorCobria('ACCESS_DENIED', 'Acceso denegado');
    }

    auditar({ ...base, resultado: 'permitido', codigo: 'ACCESS_GRANTED', ocurridoEn: ahora() });
  };
}

