export class ErrorCobria extends Error {
  constructor(codigo, mensaje, parametros = {}) {
    super(mensaje);
    this.name = 'ErrorCobria';
    this.codigo = codigo;
    this.parametros = Object.freeze({ ...parametros });
  }
}

import { ErrorCobria } from './error-cobria.mjs';

export class Observacion {
  constructor({ id, ambito, especie, cantidad, revision = 1, observadaEn }) {
    if (!id?.trim()) throw new ErrorCobria('OBS_ID_REQUIRED', 'El identificador es obligatorio');
    if (!ambito?.trim()) throw new ErrorCobria('OBS_SCOPE_REQUIRED', 'El ámbito es obligatorio');
    if (!especie?.trim()) throw new ErrorCobria('OBS_SPECIES_REQUIRED', 'La especie es obligatoria');
    if (!Number.isInteger(cantidad) || cantidad < 1) throw new ErrorCobria('OBS_QUANTITY_INVALID', 'La cantidad debe ser positiva');
    if (!Number.isInteger(revision) || revision < 1) throw new ErrorCobria('OBS_REVISION_INVALID', 'La revisión debe ser positiva');

    const instante = new Date(observadaEn);
    if (Number.isNaN(instante.getTime())) throw new ErrorCobria('OBS_DATE_INVALID', 'La fecha de observación no es válida');

    this.id = id;
    this.ambito = ambito;
    this.especie = especie;
    this.cantidad = cantidad;
    this.revision = revision;
    this.observadaEn = instante.toISOString();
    Object.freeze(this);
  }
}

import { Observacion } from '../../domain/observacion.mjs';
import { ErrorCobria } from '../../domain/error-cobria.mjs';

export class ObservacionDater {
  haciaFisico(observacion) {
    return {
      a: observacion.id,
      b: observacion.ambito,
      c: observacion.revision,
      d: 1,
      e: observacion.observadaEn,
      f: observacion.especie,
      g: observacion.cantidad,
    };
  }

  desdeFisico(documento) {
    if (documento?.d !== 1) throw new ErrorCobria('PHYSICAL_VERSION_UNSUPPORTED', 'Versión física no compatible', { version: documento?.d });
    return new Observacion({
      id: documento.a,
      ambito: documento.b,
      revision: documento.c,
      observadaEn: documento.e,
      especie: documento.f,
      cantidad: documento.g,
    });
  }
}

const titulos = Object.freeze({
  validation: 'La solicitud no es válida',
  authorization: 'La operación no está autorizada',
  conflict: 'La operación entra en conflicto con el estado actual',
  integrity: 'No fue posible verificar el resultado',
  compatibility: 'La versión no es compatible',
  infrastructure: 'El servicio no está disponible temporalmente',
});

const categorias = Object.freeze({
  ACCESS_DENIED: 'authorization',
  IDEMPOTENCY_CONFLICT: 'conflict',
  STALE_REVISION: 'conflict',
  PROJECTION_VERIFICATION_FAILED: 'integrity',
  PHYSICAL_VERSION_UNSUPPORTED: 'compatibility',
  PROVIDER_FAILURE: 'infrastructure',
});

export function crearProblemaHttp(error, estado, traducir, traceId = 'sin-traza') {
  const category = categorias[error.codigo] ?? 'validation';
  return {
    contentType: 'application/problem+json',
    body: {
      type: `https://cobria.example.invalid/problemas/${error.codigo.toLowerCase().replaceAll('_', '-')}`,
      title: titulos[category],
      status: estado,
      code: error.codigo,
      detail: traducir(error.codigo),
      traceId,
    },
  };
}

import { crearProblemaHttp } from './problema-http.mjs';

export class RegistrarObservacionController {
  constructor(registrarObservacion, traducirError) {
    this.registrarObservacion = registrarObservacion;
    this.traducirError = traducirError;
  }

  async ejecutar(solicitud) {
    try {
      const resultado = await this.registrarObservacion.ejecutar(solicitud.cuerpo, solicitud.contexto);
      return { estado: 201, cuerpo: { dato: resultado } };
    } catch (error) {
      const estados = {
        ACCESS_DENIED: 403,
        IDEMPOTENCY_CONFLICT: 409,
        STALE_REVISION: 409,
        PROJECTION_VERIFICATION_FAILED: 422,
        PHYSICAL_VERSION_UNSUPPORTED: 422,
      };
      if (error.codigo) {
        const estado = estados[error.codigo] ?? 400;
        const problema = crearProblemaHttp(error, estado, this.traducirError, solicitud.contexto?.traceId);
        return {
          estado,
          contentType: problema.contentType,
          cuerpo: { ...problema.body, codigo: problema.body.code, mensaje: problema.body.detail },
        };
      }
      throw error;
    }
  }
}

