import { performance } from "node:perf_hooks";
import { createHash } from "node:crypto";
import { equivalentDocuments } from "./oracle.mjs";

const duration = async fn => { const start = performance.now(); const value = await fn(); return { value, ms: performance.now() - start }; };
const hash = value => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const normalize = values => values.map(({id, scope, status, value, revision}) => ({id, scope, status, value, revision})).sort((a,b)=>a.id.localeCompare(b.id));
const project = doc => doc.status === "activo" ? {...doc, projected:true, sourceRevision:doc.revision} : null;

export function dataset(size, scope = "bosque-sur") {
  return Array.from({length:size}, (_,i) => ({ id:`doc-${i}`, scope, status:i%3===0?"activo":"cerrado", value:(i*17)%997, revision:1, eventTime:i }));
}

export async function loadCanonical(adapter, docs) {
  if (adapter.putMany) await adapter.putMany("canonical", docs[0]?.scope, docs);
  else for (const doc of docs) await adapter.put("canonical", doc.scope, doc.id, doc);
}

export async function runConformance(adapter, {engine, size=1000, scope="bosque-sur"}={}) {
  await adapter.reset();
  const docs = dataset(size, scope);
  const foreignScope = "bosque-norte";
  const foreignDocs = dataset(Math.max(3, Math.ceil(size / 10)), foreignScope);
  await loadCanonical(adapter, docs);
  await loadCanonical(adapter, foreignDocs);
  const canonicalMetrics = adapter.snapshot();

  const p1Canonical = await duration(async () => (await adapter.list("canonical", scope)).filter(x=>x.status==="activo"));
  const activeDocs=docs.map(project).filter(Boolean);
  if (adapter.putMany) await adapter.putMany("projection-v1",scope,activeDocs);
  else for (const doc of activeDocs) await adapter.put("projection-v1", scope, doc.id, doc);
  const p1Projection = await duration(() => adapter.list("projection-v1", scope));
  const expectedProjection = p1Canonical.value.map(project).filter(Boolean);
   const equivalentP1 = equivalentDocuments(expectedProjection, p1Projection.value);

  const beforeP2 = adapter.snapshot();
  const changed = {...docs[0], revision:2, value:docs[0].value+1};
  await adapter.put("canonical", scope, changed.id, changed);
  await adapter.put("projection-v1", scope, changed.id, changed);
  const afterP2 = adapter.snapshot();
  const p2Writes = afterP2.writes-beforeP2.writes;
  const p2Bytes = afterP2.bytesWritten-beforeP2.bytesWritten;
  const converged = (await adapter.list("projection-v1", scope)).some(x=>x.id===changed.id&&x.revision===changed.revision&&x.value===changed.value);

  const rebuild = async () => {
    await adapter.clear("projection-candidate", scope);
    const source=await adapter.list("canonical", scope);
    const projected=source.map(project).filter(Boolean);
    if (adapter.putMany) await adapter.putMany("projection-candidate",scope,projected);
    else for (const doc of projected) await adapter.put("projection-candidate", scope, doc.id, doc);
    return adapter.list("projection-candidate", scope);
  };
  const r1 = await duration(rebuild);
  const canonicalAfter = await adapter.list("canonical", scope);
  const expectedAfter=canonicalAfter.map(project).filter(Boolean);
   const r1Equivalent = equivalentDocuments(expectedAfter, r1.value);
  const r1Repeat = await rebuild();
   const r1Idempotent = equivalentDocuments(r1.value, r1Repeat);

  // Una candidata inválida no puede reemplazar la versión publicada.
  const publishedBefore=await adapter.list("projection-v1",scope);
  const invalidCandidate=r1Repeat.slice(1);
   const invalidRejected=!equivalentDocuments(expectedAfter, invalidCandidate);
  const publishedAfterRejected=await adapter.list("projection-v1",scope);
   const activePreserved=equivalentDocuments(publishedBefore, publishedAfterRejected);

  // Reconstrucción incremental: aplicar un cambio sobre una copia completa válida.
  const incrementalDoc={...canonicalAfter.find(x=>x.status==="activo"),revision:3,value:777};
  await adapter.put("canonical",scope,incrementalDoc.id,incrementalDoc);
  const incremental=[...r1Repeat.filter(x=>x.id!==incrementalDoc.id),project(incrementalDoc)].filter(Boolean);
  const canonicalIncremental=(await adapter.list("canonical",scope)).map(project).filter(Boolean);
   const incrementalEquivalent=equivalentDocuments(incremental, canonicalIncremental);

  let missingScopeRejected = false;
  try { await adapter.list("canonical", ""); } catch { missingScopeRejected = true; }
  const primary = await adapter.list("canonical", scope);
  const foreign = await adapter.list("canonical", foreignScope);
  const foreignInPrimary=primary.filter(x=>x.scope!==scope).length;
  const primaryInForeign=foreign.filter(x=>x.scope!==foreignScope).length;
  let manipulatedScopeRejected=false;
  try { await adapter.put("canonical",scope,"scope-attack",{id:"scope-attack",scope:foreignScope,revision:1,status:"activo",value:1}); } catch { manipulatedScopeRejected=true; }
  const s1 = missingScopeRejected && manipulatedScopeRejected && foreign.length===foreignDocs.length && foreignInPrimary===0 && primaryInForeign===0;

  const analyticSource=(await adapter.list("canonical",scope)).filter(x=>x.eventTime < Math.floor(size*.8));
  const analytic=analyticSource.map(x=>({id:x.id,scope:x.scope,revision:x.revision,feature:x.value%7}));
  await adapter.clear("analytic-v1",scope);
  if(adapter.putMany) await adapter.putMany("analytic-v1",scope,analytic); else for(const row of analytic) await adapter.put("analytic-v1",scope,row.id,row);
  const analyticStored=await adapter.list("analytic-v1",scope);
  const manifest = {
    contract:"COBRIA Core 1.0", engine, scope, size,
    sources:[{kind:"canonical", scope, count:analyticSource.length, hash:hash(normalize(analyticSource))}],
    transform:{name:"modulo-siete", version:1},
    partition:{strategy:"temporal", trainUntil:Math.max(0,Math.floor(size*.8)-1), testFrom:Math.floor(size*.8)},
    evidence:{available:analyticStored.length>0, abstain:analyticStored.length===0}
  };
  await adapter.clear("analytic-v1",scope);
  const rebuiltAnalytic=analyticSource.map(x=>({id:x.id,scope:x.scope,revision:x.revision,feature:x.value%7}));
  const analyticReproducible=hash(analytic)===hash(rebuiltAnalytic);
  // La abstención se observa después de retirar el derivado, no desde una constante.
  const absentEvidence = await adapter.list("analytic-v1", scope);
  const abstainsWithoutEvidence = absentEvidence.length === 0 && analyticSource.length > 0;
  const noTemporalLeakage=analyticSource.every(x=>x.eventTime<manifest.partition.testFrom);
  const a1 = Boolean(manifest.sources[0].hash && manifest.partition.testFrom > manifest.partition.trainUntil && analyticReproducible && abstainsWithoutEvidence && noTemporalLeakage);

  return {
    engine,size,scope,
    P1:{pass:equivalentP1,canonicalMs:p1Canonical.ms,projectionMs:p1Projection.ms,ratio:p1Projection.ms/Math.max(p1Canonical.ms,0.0001)},
    P2:{pass:p2Writes===2&&p2Bytes>0&&converged,writes:p2Writes,writeAmplification:p2Writes,bytesWritten:p2Bytes,converged,baselineWrites:canonicalMetrics.writes},
    R1:{pass:r1Equivalent&&r1Idempotent&&incrementalEquivalent&&invalidRejected&&activePreserved,rebuildMs:r1.ms,equivalent:r1Equivalent,idempotent:r1Idempotent,incrementalEquivalent,invalidRejected,activePreserved,count:r1.value.length},
    S1:{pass:s1,missingScopeRejected,manipulatedScopeRejected,foreignSeeded:foreign.length,foreignDocuments:foreignInPrimary+primaryInForeign},
    A1:{pass:a1,manifestHash:hash(manifest),analyticReproducible,noTemporalLeakage,abstainsWithoutEvidence,manifest}
  };
}

import { createHash } from "node:crypto";

export const huella = value => createHash("sha256").update(JSON.stringify(value)).digest("hex");

export function exigirAmbito(scope) {
  if (typeof scope !== "string" || !scope.trim()) throw new Error("COBRIA-SCP-001: ámbito requerido");
  return scope.trim();
}

export function exigirCoincidenciaAmbito(scope, value) {
  const safe = exigirAmbito(scope);
  if (value?.scope !== undefined && exigirAmbito(value.scope) !== safe) {
    throw new Error("COBRIA-SCP-001: el ámbito del documento no coincide con la operación");
  }
  return safe;
}

export function documentoCobria(input) {
  const scope = exigirAmbito(input.scope);
  if (!input.id) throw new Error("COBRIA-ID-001: identidad requerida");
  if (!Number.isInteger(input.revision) || input.revision < 1) throw new Error("COBRIA-REV-001: revisión inválida");
  return Object.freeze({ schemaVersion: 1, ...input, id: String(input.id), scope });
}

export function manifiestoCobria({ sources, transform, partition, evidence }) {
  if (!sources?.length || sources.some(source => !source.hash || !source.scope)) {
    throw new Error("COBRIA-ANA-001: fuentes incompletas");
  }
  const manifest = {
    contract: "COBRIA Core 1.1",
    createdAt: new Date().toISOString(),
    sources,
    transform,
    partition,
    evidence
  };
  return Object.freeze({ ...manifest, hash: huella(manifest) });
}

export class RepositorioCobria {
  constructor(adapter) { this.adapter = adapter; }
  async guardar(doc) {
    const next = documentoCobria(doc);
    const current = (await this.adapter.list("canonical", next.scope)).find(item => item.id === next.id);
    if (current && current.revision > next.revision) throw new Error("COBRIA-REV-001: revisión obsoleta");
    await this.adapter.put("canonical", next.scope, next.id, next);
    return next;
  }
  listar(scope) { return this.adapter.list("canonical", exigirAmbito(scope)); }
}

export class ProyeccionCobria {
  constructor(adapter, { name, version, transform = value => value, verify }) {
    this.adapter = adapter;
    this.name = name;
    this.version = version;
    this.transform = transform;
    this.verify = verify;
  }
  async reconstruir(scope, canonical) {
    exigirAmbito(scope);
    const candidate = `${this.name}-candidate-v${this.version}`;
    await this.adapter.clear(candidate, scope);
    for (const item of canonical) await this.adapter.put(candidate, scope, item.id, this.transform(item));
    const values = await this.adapter.list(candidate, scope);
    if (!this.verify(canonical, values)) throw new Error("COBRIA-EQV-001: candidata rechazada");
    return { candidate, values, hash: huella(values) };
  }
}

export class AutorizadorAmbito {
  constructor(permissions = {}) { this.permissions = new Map(Object.entries(permissions)); }
  exigir(principal, scope, action = "read") {
    exigirAmbito(scope);
    const allowed = this.permissions.get(principal) || [];
    if (!allowed.some(item => item === "*" || item === action || item === `${action}:${scope}` || item === `*:${scope}`)) {
      throw new Error("COBRIA-AUTH-001: operación no autorizada para el ámbito");
    }
    return true;
  }
}

export class PublicadorVersionado {
  constructor(adapter, { name }) { this.adapter = adapter; this.name = name; }
  async active(scope) {
    const rows = await this.adapter.list("publication-catalog", scope);
    return rows.find(row => row.id === this.name)?.active || null;
  }
  async publicar(scope, candidate, { version, expectedHash }) {
    exigirAmbito(scope);
    if (!version || !expectedHash) throw new Error("COBRIA-PUB-001: versión y huella requeridas");
    const values = await this.adapter.list(candidate, scope);
    if (huella(values) !== expectedHash) throw new Error("COBRIA-EQV-001: candidata no verificable");
    const previous = await this.active(scope);
    await this.adapter.put("publication-catalog", scope, this.name, {
      id: this.name, scope, revision: Date.now(), active: version, previous,
      candidate, hash: expectedHash
    });
    return { active: version, previous };
  }
  async rollback(scope) {
    const rows = await this.adapter.list("publication-catalog", scope);
    const record = rows.find(row => row.id === this.name);
    if (!record?.previous) throw new Error("COBRIA-PUB-002: no existe versión anterior");
    await this.adapter.put("publication-catalog", scope, this.name, {
      ...record, revision: Date.now(), active: record.previous, previous: null
    });
    return record.previous;
  }
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { EXIT } from './toolkit.mjs';

export const GENERATOR_TYPES=Object.freeze(['proyecto','modulo','entidad','valor','caso-uso','puerto','adaptador','dater','nodo','catalogo','function','evento','adr','prueba','runbook']);
const TYPE_LABELS=Object.freeze({'proyecto':'Proyecto','modulo':'Módulo','entidad':'Entidad','valor':'Objeto de valor','caso-uso':'Caso de uso','puerto':'Puerto','adaptador':'Adaptador','dater':'Dater','nodo':'Nodo','catalogo':'Catálogo','function':'Function','evento':'Evento','adr':'ADR','prueba':'Prueba','runbook':'Runbook'});

function slugify(value){return value.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function pascal(value){return value.split('-').map(x=>x.charAt(0).toUpperCase()+x.slice(1)).join('');}

function artifacts(type,name,root){
  if(!GENERATOR_TYPES.includes(type))throw Object.assign(new Error(`Tipo no soportado: ${type}`),{code:'CLI_GENERATOR_TYPE_INVALID',exit:EXIT.USAGE});
  if(!/^[\p{L}\p{N} _-]{2,80}$/u.test(name??''))throw Object.assign(new Error('El nombre solo admite letras, números, espacios, guion y guion bajo (2–80 caracteres).'),{code:'CLI_GENERATOR_NAME_INVALID',exit:EXIT.USAGE});
  const slug=slugify(name??'');
  const key=`${type}-${slug}`;const symbol=pascal(slug);const label=TYPE_LABELS[type];
  const code=`/** ${label} generado por COBRIA. Complete el contrato sin añadir dependencias de proveedor. */
export const definition = Object.freeze({ id: '${key}', type: '${type}', name: ${JSON.stringify(name)}, version: '0.1.0' });

export class ${symbol} {
  constructor(dependencies = {}) { this.dependencies = Object.freeze({ ...dependencies }); }
  execute(input) { if (input == null) throw new Error('INPUT_REQUIRED'); return { accepted: true, input }; }
}
`;
  const test=`import test from 'node:test';
import assert from 'node:assert/strict';
import { definition, ${symbol} } from '../../src/generated/${key}.mjs';

test('${key} conserva identidad y rechaza entrada ausente', () => {
  assert.equal(definition.id, '${key}');
  const subject = new ${symbol}();
  assert.throws(() => subject.execute(null), /INPUT_REQUIRED/);
  assert.equal(subject.execute({ id: 'ejemplo' }).accepted, true);
});
`;
  const doc=`# ${label}: ${name}

**ID:** \`${key}\`  
**Versión:** 0.1.0  
**Estado:** propuesto  
**Responsable:** POR-DEFINIR

## Propósito

Describa el problema observable y por qué este artefacto es necesario.

## Contrato

Declare entrada, precondiciones, salida, errores, ámbito, evidencia y límites.

## Criterios de aceptación

- [ ] caso permitido probado;
- [ ] caso negativo probado;
- [ ] dependencias y consecuencias documentadas.
`;
  const refs=[`src/generated/${key}.mjs`,`test/generated/${key}.test.mjs`,`docs/generated/${key}.md`];
  const manifest=JSON.stringify({schemaVersion:'1.0.0',id:key,type,name,version:'0.1.0',owner:'POR-DEFINIR',status:'proposed',artifacts:refs,generatedBy:'cobria-toolkit-phase-13'},null,2)+'
';
  return [
    [path.join(root,refs[0]),code],[path.join(root,refs[1]),test],[path.join(root,refs[2]),doc],
    [path.join(root,'.cobria/generated',`${key}.json`),manifest]
  ];
}

export async function generate({type,name,directory}){
  const root=path.resolve(directory);const planned=artifacts(type,name,root);const conflicts=[];const created=[];const unchanged=[];
  for(const [file,content] of planned){const existing=await fs.readFile(file,'utf8').catch(error=>error.code==='ENOENT'?null:Promise.reject(error));if(existing===null)continue;if(existing===content)unchanged.push(path.relative(root,file));else conflicts.push(path.relative(root,file));}
  if(conflicts.length)throw Object.assign(new Error(`No se sobrescribieron archivos divergentes: ${conflicts.join(', ')}`),{code:'CLI_GENERATOR_CONFLICT',exit:EXIT.CONFLICT,conflicts});
  for(const [file,content] of planned){if(unchanged.includes(path.relative(root,file)))continue;await fs.mkdir(path.dirname(file),{recursive:true});try{await fs.writeFile(file,content,{flag:'wx'});created.push(path.relative(root,file));}catch(error){if(error.code==='EEXIST')throw Object.assign(new Error(`Conflicto concurrente: ${path.relative(root,file)}`),{code:'CLI_GENERATOR_CONFLICT',exit:EXIT.CONFLICT});throw error;}}
  return {type,name,root,created,unchanged,status:created.length?'generated':'unchanged'};
}

import test from "node:test";
import assert from "node:assert/strict";
import { LokiJsAdapter } from "../src/adapters/lokijs-adapter.mjs";
import { documentoCobria, RepositorioCobria, ProyeccionCobria, PublicadorVersionado, AutorizadorAmbito, huella } from "../src/core/cobria.mjs";

test("documento exige ámbito, identidad y revisión", () => {
  assert.throws(() => documentoCobria({id:"x",revision:1}), /SCP-001/);
  assert.throws(() => documentoCobria({scope:"sur",revision:1}), /ID-001/);
  assert.throws(() => documentoCobria({id:"x",scope:"sur",revision:0}), /REV-001/);
});

test("repositorio rechaza regresión de revisión", async () => {
  const adapter = new LokiJsAdapter();
  const repo = new RepositorioCobria(adapter);
  await repo.guardar({id:"ave-1",scope:"bosque-sur",revision:2,species:"colibrí"});
  await assert.rejects(() => repo.guardar({id:"ave-1",scope:"bosque-sur",revision:1}), /REV-001/);
  await adapter.close();
});

test("adaptador rechaza un documento cuyo ámbito contradice la operación", async () => {
  const adapter = new LokiJsAdapter();
  await assert.rejects(
    () => adapter.put("canonical", "bosque-sur", "ataque-1", {id:"ataque-1",scope:"bosque-norte",revision:1}),
    /SCP-001/
  );
  await adapter.close();
});

test("proyección se reconstruye y verifica fuera de la versión activa", async () => {
  const adapter = new LokiJsAdapter();
  const canonical = [{id:"rana-1",scope:"bosque-sur",revision:1,species:"rana de ojos rojos"}];
  const projection = new ProyeccionCobria(adapter, {name:"busqueda",version:1,verify:(a,b)=>huella(a)===huella(b)});
  const result = await projection.reconstruir("bosque-sur", canonical);
  assert.equal(result.values.length, 1);
  assert.match(result.candidate, /candidate/);
  await adapter.close();
});

test("publicador cambia versión y permite rollback sin aceptar candidata corrupta", async () => {
  const adapter = new LokiJsAdapter();
  const publisher = new PublicadorVersionado(adapter, { name: "busqueda" });
  const candidate = [{ id: "rana-1", scope: "bosque-sur", revision: 1, value: 1 }];
  await adapter.put("candidate-v1", "bosque-sur", "rana-1", candidate[0]);
  await assert.rejects(() => publisher.publicar("bosque-sur", "candidate-v1", { version: "v1", expectedHash: "bad" }), /EQV-001/);
  const hash = huella(await adapter.list("candidate-v1", "bosque-sur"));
  await publisher.publicar("bosque-sur", "candidate-v1", { version: "v1", expectedHash: hash });
  await adapter.put("candidate-v2", "bosque-sur", "rana-1", { ...candidate[0], value: 2 });
  const hash2 = huella(await adapter.list("candidate-v2", "bosque-sur"));
  await publisher.publicar("bosque-sur", "candidate-v2", { version: "v2", expectedHash: hash2 });
  assert.equal(await publisher.active("bosque-sur"), "v2");
  assert.equal(await publisher.rollback("bosque-sur"), "v1");
  assert.equal(await publisher.active("bosque-sur"), "v1");
  await adapter.close();
});

test("fallo al publicar conserva la versión activa anterior", async () => {
  class FailingCatalogAdapter extends LokiJsAdapter {
    constructor() { super(); this.failCatalog = false; }
    async put(kind, scope, id, value) {
      if (this.failCatalog && kind === "publication-catalog") throw new Error("injected publication failure");
      return super.put(kind, scope, id, value);
    }
  }
  const adapter = new FailingCatalogAdapter();
  const publisher = new PublicadorVersionado(adapter, { name: "busqueda" });
  await adapter.put("candidate-v1", "sur", "a", { id: "a", scope: "sur", revision: 1, value: 1 });
  const hash = huella(await adapter.list("candidate-v1", "sur"));
  await publisher.publicar("sur", "candidate-v1", { version: "v1", expectedHash: hash });
  await adapter.put("candidate-v2", "sur", "a", { id: "a", scope: "sur", revision: 2, value: 2 });
  const hash2 = huella(await adapter.list("candidate-v2", "sur"));
  adapter.failCatalog = true;
  await assert.rejects(() => publisher.publicar("sur", "candidate-v2", { version: "v2", expectedHash: hash2 }), /publication failure/);
  assert.equal(await publisher.active("sur"), "v1");
  await adapter.close();
});

test("autorizador separa permisos de lectura y escritura por ámbito", () => {
  const auth = new AutorizadorAmbito({ lector: ["read:sur"], escritor: ["write:sur"] });
  assert.equal(auth.exigir("lector", "sur", "read"), true);
  assert.throws(() => auth.exigir("lector", "sur", "write"), /AUTH-001/);
  assert.throws(() => auth.exigir("lector", "norte", "read"), /AUTH-001/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { generate, GENERATOR_TYPES } from '../src/generator.mjs';

test('los quince generadores crean código, prueba, documento y manifiesto',async()=>{
  const root=mkdtempSync(path.join(tmpdir(),'cobria-generators-'));
  for(const type of GENERATOR_TYPES){const result=await generate({type,name:`Ejemplo ${type}`,directory:root});assert.equal(result.created.length,4);assert.equal(result.status,'generated');}
});

test('repetir una generación idéntica no cambia archivos',async()=>{
  const root=mkdtempSync(path.join(tmpdir(),'cobria-idempotent-'));
  const first=await generate({type:'entidad',name:'Observación',directory:root});
  const file=path.join(root,first.created[0]);const before=readFileSync(file,'utf8');
  const second=await generate({type:'entidad',name:'Observación',directory:root});
  assert.equal(second.status,'unchanged');assert.equal(second.created.length,0);assert.equal(second.unchanged.length,4);assert.equal(readFileSync(file,'utf8'),before);
});

test('un archivo divergente detiene todo sin sobrescribir',async()=>{
  const root=mkdtempSync(path.join(tmpdir(),'cobria-conflict-'));
  const first=await generate({type:'puerto',name:'Repositorio',directory:root});const file=path.join(root,first.created[0]);writeFileSync(file,'trabajo humano\n');
  await assert.rejects(()=>generate({type:'puerto',name:'Repositorio',directory:root}),error=>error.code==='CLI_GENERATOR_CONFLICT');
  assert.equal(readFileSync(file,'utf8'),'trabajo humano\n');
});

test('rechaza nombres que podrían escapar rutas o inyectar código',async()=>{
  const root=mkdtempSync(path.join(tmpdir(),'cobria-name-'));
  await assert.rejects(()=>generate({type:'entidad',name:'../../escape',directory:root}),error=>error.code==='CLI_GENERATOR_NAME_INVALID');
  await assert.rejects(()=>generate({type:'desconocido',name:'Ejemplo',directory:root}),error=>error.code==='CLI_GENERATOR_TYPE_INVALID');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import { auditProject, analyzeFileImpact } from '../src/auditor.mjs';
const fixtures=path.resolve(import.meta.dirname,'../fixtures/audit-phase14');

